// Region data generated by scripts/convex/build-region-data.mjs and the
// source list from config/regions.json. Rebuild + redeploy after republishing
// a region's v2 bundle so bundleEnd, clip and static mask stay in sync.
import us from "./regionData/us.json";
import iberia from "./regionData/iberia.json";
import config from "../config/regions.json";
import type { RegionData, SourceConfig } from "./lib/nrtCore";

export const REGIONS: Record<string, RegionData> = {
  us: us as unknown as RegionData,
  iberia: iberia as unknown as RegionData,
};
export const SOURCES = config.sources as SourceConfig[];
// The daily pull fetches near-real-time products only.
export const NRT_SOURCES = SOURCES.filter((s) => s.kind === "NRT");
export const regionIds = Object.keys(REGIONS);
